225: /// Check if port is listening via raw TCP connect
226: /// SOURCE: man 2 socket, man 2 connect — TCP connection check
227: fn isPortListening(port: u16) bool {
228:     const fd = std.os.linux.socket(std.posix.AF.INET, std.posix.SOCK.STREAM | std.posix.SOCK.CLOEXEC, 0);
229:     if (fd < 0) return false;
230:     defer _ = std.os.linux.close(@intCast(fd));
231: 
232:     var addr: std.posix.sockaddr.in = .{
233:         .port = std.mem.nativeToBig(u16, port),
234:         .addr = std.mem.nativeToBig(u32, 0x7F000001),
235:     };
236:     const connect_rc = std.os.linux.connect(@intCast(fd), @ptrCast(&addr), @sizeOf(std.posix.sockaddr.in));
237:     return connect_rc == 0;
238: }
