318:             }
319:         }
320: 
321:         // Port readiness poll — foxbridge starts CDP server in a goroutine,
322:         // so port may not be listening immediately after the log message.
323:         var port_ready = false;
324:         var port_poll_ts: std.posix.timespec = undefined;
325:         _ = std.os.linux.clock_gettime(.MONOTONIC, &port_poll_ts);
326:         const port_poll_start_ns = @as(i64, @intCast(port_poll_ts.sec)) * std.time.ns_per_s + @as(i64, @intCast(port_poll_ts.nsec));
327:         while (true) {
328:             _ = std.os.linux.clock_gettime(.MONOTONIC, &port_poll_ts);
329:             const now_ns = @as(i64, @intCast(port_poll_ts.sec)) * std.time.ns_per_s + @as(i64, @intCast(port_poll_ts.nsec));
330:             if (now_ns - port_poll_start_ns >= 10 * std.time.ns_per_s) break;
331:             if (isPortListening(port)) {
332:                 port_ready = true;
333:                 break;
334:             }
335:             _ = std.os.linux.nanosleep(&std.os.linux.timespec{ .sec = 0, .nsec = 200 * std.time.ns_per_ms }, null);
336:         }
337:         if (!port_ready) {
338:             log.err(.browser, "VulpineOS readiness log'u geldi ama port {d} dinlemiyor", .{port});
339:             return BrowserInitError.SpawnFailed;
340:         }
341: 
342:         log.info(.browser, "VulpineOS foxbridge CDP ready on port {d}", .{port});
343: 
344:         const proxy_owned: ?[]u8 = if (proxy_host_port_arg) |p| try allocator.dupe(u8, p) else null;
345: 
346:         return StealthBrowser{
347:             .allocator = allocator,
348:             .io = io,
349:             .child = std.mem.zeroes(process.Child),
350:             .profile_dir = "",
351:             .pid = null,
352:             .port = port,
353:             .proxy_host_port = proxy_owned,
354:         };
355:     }
