364:             _ = std.os.linux.nanosleep(&std.os.linux.timespec{ .sec = 0, .nsec = 100 * std.time.ns_per_ms }, null);
365:             _ = std.c.waitpid(pid, null, std.os.linux.W.NOHANG);
366:         }
367:         // self.port'da dinleyen TÜM process'leri öldür
368:         // runuser + vulpineos.bin + camoufox zincirini temizler
369:         var fuser_buf: [64]u8 = undefined;
370:         const fuser_cmd = std.fmt.bufPrintZ(&fuser_buf, "fuser -k {d}/tcp 2>/dev/null", .{self.port}) catch return;
371:         _ = system(fuser_cmd.ptr);
372:         forceKillInstanceCamoufox(self.port);
