display.text:
// =============================================================================
// Module — Stealth Browser Initialization (VulpineOS/Camoufox Process)
// Target: VulpineOS serve --headless --binary camoufox (CDP on dynamic port)
// =============================================================================
//
// SOURCE: comoufox-entegrasyon/VulpineOS/docs/VulpineOS-README.md
// SOURCE: comoufox-entegrasyon/VulpineOS/docs/FoxBridge/camoufox-cdp.md
// SOURCE: man 8 runuser — run command as specified user
// SOURCE: Camoufox/Firefox sandbox — refuses to run as root (UID 0)
//
// NETWORK STACK ANALYSIS:
// [1] Process spawning: VulpineOS serve --headless --binary camoufox --port {port}
// [2] Root avoidance: Engine runs as root (sudo for raw sockets), VulpineOS must run as non-root
// [3] CDP: WebSocket on localhost:{port} for Runtime.evaluate JS injection
// [4] UFW/iptables: No firewall rules needed — VulpineOS makes outbound HTTPS only
// [5] Port isolation: Tüm kaynaklar (profil, script, log) port bazlı türetilir → paralel run destegi

const std = @import("std");
const mem = std.mem;
const process = std.process;
const Io = std.Io;
const log = @import("log.zig");

extern "c" fn system(command: [*:0]const u8) c_int;

// ---------------------------------------------------------------------------
// Error Types
// ---------------------------------------------------------------------------

pub const BrowserInitError = error{
    OutOfMemory,
    ChromeNotFound,
    SpawnFailed,
    ProfileDirCreationFailed,
    PreferencesWriteFailed,
    MkdtempFailed,
    CleanupFailed,
};

// ---------------------------------------------------------------------------
// Constants — VulpineOS/Camoufox configuration
// ---------------------------------------------------------------------------

pub const PROJECT_ROOT = "/home/void0x14/Documents/ihsan-agama-verilen-destek/doggystyle";
pub const FOXBRIDGE_BINARY = PROJECT_ROOT ++ "/comoufox-entegrasyon/foxbridge/foxbridge";
pub const VULPINEOS_BINARY = PROJECT_ROOT ++ "/comoufox-entegrasyon/VulpineOS/vulpineos.bin";
pub const VULPINEOS_BINARY_REL = "comoufox-entegrasyon/VulpineOS/vulpineos.bin";
pub const CAMOUFOX_BINARY = "/home/void0x14/.cache/camoufox/camoufox";
pub var VULPINEOS_DEFAULT_PORT: u16 = 9222;
pub const VULPINEOS_POLL_TIMEOUT_S: u8 = 30;
pub const VULPINEOS_POLL_INTERVAL_MS: u16 = 1000;
pub const VULPINEOS_USER = "void0x14";
pub const CAMOU_CONFIG_SCRIPT = PROJECT_ROOT ++ "/comoufox-entegrasyon/VulpineOS/scripts/generate_camou_config.py";
pub const CAMOU_CONFIG_JSON = PROJECT_ROOT ++ "/comoufox-entegrasyon/VulpineOS/camou_launch_config.json";
pub const CAMOU_CONFIG_ENV_FILE = PROJECT_ROOT ++ "/comoufox-entegrasyon/VulpineOS/camou_config_env1";


// ---------------------------------------------------------------------------
// Utility Functions
// ---------------------------------------------------------------------------

/// Calls Camoufox Python launch_options() to generate a full stealth config
/// (BrowserForge fingerprint, navigator, fonts, WebGL, canvas/audio seeds, WebRTC, etc.)
/// and writes the CAMOU_CONFIG_1 env value to a file VulpineOS can inherit.
///
/// SOURCE: Camoufox docs 03-python-interface.md — Python library auto-generates & injects
///   unique device characteristics (OS, device info, navigator, fonts, headers, screen/viewport, addons).
/// SOURCE: CONTRIBUTING.md:35 — raw binary path uses CAMOU_CONFIG env for global fingerprint mode.
/// SOURCE: camoufox.utils.launch_options() — generates BrowserForge fingerprints, fonts, voices,
///   WebGL, canvas/audio seeds, geoip/timezone/locale, humanize, Firefox prefs.
/// Per-port env-file path so parallel workers never clobber each other's
/// fingerprint config. Shared file caused a race: worker A writes fingerprint,
/// worker B overwrites, worker A's wrapper cats B's config -> account/session mix.
fn camouEnvPath(buf: []u8, port: u16) []const u8 {
    return std.fmt.bufPrint(buf, "{s}-{d}", .{ CAMOU_CONFIG_ENV_FILE, port }) catch CAMOU_CONFIG_ENV_FILE;
}

fn camouJsonPath(buf: []u8, port: u16) []const u8 {
    return std.fmt.bufPrint(buf, "{s}-{d}.json", .{ CAMOU_CONFIG_JSON, port }) catch CAMOU_CONFIG_JSON;
}

fn generateCamouConfig(port: u16) void {
    _ = system("mkdir -p /home/void0x14/.cache/camoufox 2>/dev/null");

    // glxtest ve vaapitest'i Firefox dizininden Camoufox dizinine kopyala
    // Bu dosyalar WebGL/VA-API icin zorunludur — yoksa context olusturulamaz
    // SOURCE: Firefox GfxInfo — glxtest GPU test binary'si
    _ = system("cp /usr/lib/firefox/glxtest /home/void0x14/.cache/camoufox/browsers/official/150.0.2-alpha.26/glxtest 2>/dev/null && chmod +x /home/void0x14/.cache/camoufox/browsers/official/150.0.2-alpha.26/glxtest 2>/dev/null");
    _ = system("cp /usr/lib/firefox/vaapitest /home/void0x14/.cache/camoufox/browsers/official/150.0.2-alpha.26/vaapitest 2>/dev/null && chmod +x /home/void0x14/.cache/camoufox/browsers/official/150.0.2-alpha.26/vaapitest 2>/dev/null");

    var env_path_buf: [512]u8 = undefined;
    var json_path_buf: [512]u8 = undefined;
    const env_path = camouEnvPath(&env_path_buf, port);
    const json_path = camouJsonPath(&json_path_buf, port);

    var cmd_buf: [4096]u8 = undefined;
    const cmd = std.fmt.bufPrintZ(&cmd_buf,
        \\ sudo -u {s} PYTHONPATH="{s}" python3 {s} {s} {s}
    , .{
        VULPINEOS_USER,
        PROJECT_ROOT ++ "/comoufox-entegrasyon/VulpineOS/vulpineos-src/pythonlib",
        CAMOU_CONFIG_SCRIPT, json_path, env_path,
    }) catch return;
    const rc = system(cmd.ptr);
    if (rc == 0) {
        log.info(.browser, "Camoufox fingerprint config generated via launch_options()", .{});
    } else {
        log.warn(.browser, "generateCamouConfig: launch_options() returned exit={d}", .{rc});
    }
}

fn buildSpawnWrapper(vulpineos_binary: []const u8, camoufox_binary: []const u8, port: u16, proxy_host_port: ?[]const u8) void {
    _ = vulpineos_binary;
    var env_path_buf: [512]u8 = undefined;
    const env_path = camouEnvPath(&env_path_buf, port);
    var cmd_buf: [8192]u8 = undefined;
    var proxy_flag_buf: [256]u8 = undefined;
    const proxy_flag: []const u8 = if (proxy_host_port) |proxy|
        std.fmt.bufPrint(&proxy_flag_buf, " \\\n    --proxy-server=socks5://{s}", .{proxy}) catch &[_]u8{}
    else
        &[_]u8{};
    // No --proxy => force Firefox to NEVER use a proxy (type=0 = direct connection).
    // Firefox default network.proxy.type is 5 (use system settings), which can silently
    // pick up http_proxy/https_proxy/all_proxy env or GNOME system proxy. Pin it to direct.
    // When a proxy IS supplied, foxbridge's --proxy-server owns proxy config, so skip this.
    const no_proxy_pref: []const u8 = if (proxy_host_port == null)
        "user_pref(\"network.proxy.type\", 0);\n"
    else
        "";
    const cmd = std.fmt.bufPrintZ(&cmd_buf,
         "cat > /tmp/run_vulpineos-{d}.sh << 'WRAPPER'\n"
        ++ "#!/bin/sh\n"
        ++ "unset http_proxy https_proxy all_proxy ftp_proxy socks_proxy HTTP_PROXY HTTPS_PROXY ALL_PROXY FTP_PROXY SOCKS_PROXY\n"
        ++ "CAMOU_CONFIG_1=\"$(cat {s})\"\n"
        ++ "export CAMOU_CONFIG_1\n"
        ++ "export HOME=/home/void0x14\n"
        ++ "export XDG_CONFIG_HOME=/home/void0x14/.config\n"
        ++ "export XDG_DATA_DIRS=/usr/share/ubuntu:/usr/local/share:/usr/share\n"
        ++ "export GTK_THEME=Breeze\n"
        ++ "DISPLAY=:0\n"
        ++ "export DISPLAY\n"
        ++ "# XAUTHORITY forward: runuser drops env, discover dynamically\n"
        ++ "for f in /run/user/$(id -u)/xauth_* \"$HOME/.Xauthority\"; do\n"
        ++ "    if [ -f \"$f\" ]; then\n"
        ++ "        export XAUTHORITY=\"$f\"\n"
        ++ "        break\n"
        ++ "    fi\n"
        ++ "done\n"
        ++ "PROFILE_DIR=/tmp/doggystyle-camoufox-profile-{d}\n"
        ++ "rm -rf \"$PROFILE_DIR\"\n"
        ++ "mkdir -p \"$PROFILE_DIR\"\n"
        ++ "cat > \"$PROFILE_DIR/user.js\" << 'PREFS'\n"
        ++ "user_pref(\"network.websocket.allowInsecureFromHTTPS\", true);\n"
        ++ "user_pref(\"security.mixed_content.block_active_content\", false);\n"
        ++ "{s}"
        ++ "PREFS\n"
        ++ "exec {s} --binary {s} --profile \"$PROFILE_DIR\" --port {d} -headless=false -- --width=1920 --height=941{s}\n"
        ++ "WRAPPER"
    , .{ port, env_path, port, no_proxy_pref, FOXBRIDGE_BINARY, camoufox_binary, port, proxy_flag }) catch return;
    _ = system(cmd.ptr);
    var chmod_buf: [128]u8 = undefined;
    const chmod_cmd = std.fmt.bufPrintZ(&chmod_buf, "chmod +x /tmp/run_vulpineos-{d}.sh 2>/dev/null", .{port}) catch return;
    _ = system(chmod_cmd.ptr);
}

// Kill ONLY this instance's camoufox chain, matched by its unique profile
// path (/tmp/doggystyle-camoufox-profile-<port>), which every worker/run has
// distinct. The old global `pkill -9 -f camoufox` nuked EVERY worker's browser
// system-wide: when one run finished, deinit killed all siblings still starting
// up -> at --isci 8, 49/59 runs died with "firefox started ... Killed". Scope
// the kill to the profile path so parallel workers no longer murder each other.
fn forceKillInstanceCamoufox(port: u16) void {
    var pat_buf: [96]u8 = undefined;
    const pat = std.fmt.bufPrintZ(&pat_buf, "doggystyle-camoufox-profile-{d}", .{port}) catch return;
    var cmd_buf: [160]u8 = undefined;
    const cmd = std.fmt.bufPrintZ(&cmd_buf, "pkill -9 -f {s} 2>/dev/null", .{pat}) catch return;
    var i: u32 = 0;
    while (i < 20) : (i += 1) {
        _ = system(cmd.ptr);
        var chk_buf: [160]u8 = undefined;
        const chk = std.fmt.bufPrintZ(&chk_buf, "pgrep -f {s} >/dev/null 2>&1", .{pat}) catch return;
        if (system(chk.ptr) != 0) break; // pgrep bulamadi = temiz
        _ = std.os.linux.nanosleep(&std.os.linux.timespec{ .sec = 0, .nsec = 150 * std.time.ns_per_ms }, null);
    }
}

fn waitForPortFree(port: u16, max_wait_ms: u64) void {
    var elapsed: u64 = 0;
    const step_ms: u64 = 200;
    while (elapsed < max_wait_ms) {
        if (!isPortListening(port)) return;
        _ = std.os.linux.nanosleep(&std.os.linux.timespec{ .sec = 0, .nsec = step_ms * std.time.ns_per_ms }, null);
        elapsed += step_ms;
    }
}

fn spawnVulpineosAsUser(port: u16, proxy_host_port: ?[]const u8) void {
    // [Fix race] Her run child UNIQUE port kullanir (9222 + worker_id*100 + run_no).
    // Sadece KENDI portumuzdaki stale process'i oldur. Kimsenin portuna dokunma!
    // fuser -k port/tcp, bu PORT'TAKI process'i oldurur — baska worker'in portu
    // farkli oldugu icin onlara dokunmaz.
    killPortOwner(port);
    waitForPortFree(port, 2000);
    buildSpawnWrapper(VULPINEOS_BINARY, CAMOUFOX_BINARY, port, proxy_host_port);
    var rm_buf: [128]u8 = undefined;
    const rm_cmd = std.fmt.bufPrintZ(&rm_buf, "rm -f /tmp/vulp_spawn-{d}.log 2>/dev/null; touch /tmp/vulp_spawn-{d}.log 2>/dev/null", .{port, port}) catch return;
    _ = system(rm_cmd.ptr);
    var cmd_buf: [1024]u8 = undefined;
    const cmd = std.fmt.bufPrintZ(&cmd_buf,
        "runuser -u {s} -- /tmp/run_vulpineos-{d}.sh > /tmp/vulp_spawn-{d}.log 2>&1 &"
    , .{VULPINEOS_USER, port, port}) catch return;
    log.info(.browser, "Spawning VulpineOS as user '{s}' on port {d}...", .{VULPINEOS_USER, port});
    _ = system(cmd.ptr);
}

fn waitForFoxbridgeReadyFromLog(port: u16) bool {
    var cmd_buf: [512]u8 = undefined;
    const cmd = std.fmt.bufPrintZ(&cmd_buf,
        "timeout 45 sh -c 'grep -q \"foxbridge CDP .* listening\" /tmp/vulp_spawn-{d}.log || tail -F /tmp/vulp_spawn-{d}.log | grep -m1 \"foxbridge CDP .* listening\" >/dev/null' 2>/dev/null"
    , .{port, port}) catch return false;
    const rc = system(cmd.ptr);
    return rc == 0;
}

/// Check if port is listening via raw TCP connect
/// SOURCE: man 2 socket, man 2 connect — TCP connection check
fn isPortListening(port: u16) bool {
    const fd = std.os.linux.socket(std.posix.AF.INET, std.posix.SOCK.STREAM | std.posix.SOCK.CLOEXEC, 0);
    if (fd < 0) return false;
    defer _ = std.os.linux.close(@intCast(fd));

    var addr: std.posix.sockaddr.in = .{
        .port = std.mem.nativeToBig(u16, port),
        .addr = std.mem.nativeToBig(u32, 0x7F000001),
    };
    const connect_rc = std.os.linux.connect(@intCast(fd), @ptrCast(&addr), @sizeOf(std.posix.sockaddr.in));
    return connect_rc == 0;
}

/// Kill any process listening on the given port using fuser
/// SOURCE: man 1 fuser — identify processes using files or sockets
fn killPortOwner(port: u16) void {
    var port_buf: [16]u8 = undefined;
    const port_str = std.fmt.bufPrint(&port_buf, "{d}/tcp", .{port}) catch return;
    var cmd_buf: [64]u8 = undefined;
    const cmd = std.fmt.bufPrintZ(&cmd_buf, "fuser -k {s}", .{port_str}) catch return;
    _ = system(cmd.ptr);
}

fn mapSpawnError(err: anyerror) BrowserInitError {
    return switch (err) {
        error.OutOfMemory => BrowserInitError.OutOfMemory,
        error.FileNotFound => BrowserInitError.ChromeNotFound,
        else => BrowserInitError.SpawnFailed,
    };
}

// ---------------------------------------------------------------------------
// StealthBrowser — Main struct
// ---------------------------------------------------------------------------

/// Manages a stealthy headless Chrome process with filesystem isolation
///
/// Lifecycle:
///   1. init() — Check port, spawn if needed, poll until ready
///   2. Use CDP WebSocket for Runtime.evaluate JS injection
///   3. deinit() — Kill VulpineOS process
pub const StealthBrowser = struct {
    allocator: mem.Allocator,
    io: Io,
    child: process.Child,
    profile_dir: []u8,
    pid: ?process.Child.Id,
    port: u16,
    proxy_host_port: ?[]u8,

    /// Initialize and spawn VulpineOS with Camoufox
    pub fn init(
        allocator: mem.Allocator,
        io: Io,
    ) BrowserInitError!StealthBrowser {
        return initWithBinary(allocator, io, VULPINEOS_BINARY, VULPINEOS_DEFAULT_PORT, null);
    }

    /// Initialize and spawn VulpineOS with Camoufox on specific port
    pub fn initWithPort(
        allocator: mem.Allocator,
        io: Io,
        port: u16,
        proxy_host_port_arg: ?[]const u8,
    ) BrowserInitError!StealthBrowser {
        return initWithBinary(allocator, io, VULPINEOS_BINARY, port, proxy_host_port_arg);
    }

    pub fn initWithBinary(
        allocator: mem.Allocator,
        io: Io,
        vulpineos_binary: []const u8,
        port: u16,
        proxy_host_port_arg: ?[]const u8,
    ) BrowserInitError!StealthBrowser {
        _ = vulpineos_binary;
        // SOURCE: Camoufox/Firefox sandbox — refuses to run as root (UID 0)
        // Engine runs as root (sudo for raw sockets), so VulpineOS must run as regular user.
        // Strategy: (1) Check if already running, (2) If not, spawn via runuser.

        // Step 1: Her calistirmada VulpineOS'u zorla yeniden baslat
        // Eski VulpineOS sayfasiz kalabilir — guvenli olan her seferinde temiz baslatmaktir
        generateCamouConfig(port);
        log.info(.browser, "VulpineOS starting (force restart) on port {d}...", .{port});
        spawnVulpineosAsUser(port, proxy_host_port_arg);

        if (!isPortListening(port)) {
            log.info(.browser, "VulpineOS log readiness bekleniyor (port {d})...", .{port});
            if (!waitForFoxbridgeReadyFromLog(port)) {
                log.err(.browser, "VulpineOS foxbridge readiness log'u gelmedi (port {d})", .{port});
                return BrowserInitError.SpawnFailed;
            }
        }

        // Port readiness poll — foxbridge starts CDP server in a goroutine,
        // so port may not be listening immediately after the log message.
        var port_ready = false;
        var port_poll_ts: std.posix.timespec = undefined;
        _ = std.os.linux.clock_gettime(.MONOTONIC, &port_poll_ts);
        const port_poll_start_ns = @as(i64, @intCast(port_poll_ts.sec)) * std.time.ns_per_s + @as(i64, @intCast(port_poll_ts.nsec));
        while (true) {
            _ = std.os.linux.clock_gettime(.MONOTONIC, &port_poll_ts);
            const now_ns = @as(i64, @intCast(port_poll_ts.sec)) * std.time.ns_per_s + @as(i64, @intCast(port_poll_ts.nsec));
            if (now_ns - port_poll_start_ns >= 10 * std.time.ns_per_s) break;
            if (isPortListening(port)) {
                port_ready = true;
                break;
            }
            _ = std.os.linux.nanosleep(&std.os.linux.timespec{ .sec = 0, .nsec = 200 * std.time.ns_per_ms }, null);
        }
        if (!port_ready) {
            log.err(.browser, "VulpineOS readiness log'u geldi ama port {d} dinlemiyor", .{port});
            return BrowserInitError.SpawnFailed;
        }

        log.info(.browser, "VulpineOS foxbridge CDP ready on port {d}", .{port});

        const proxy_owned: ?[]u8 = if (proxy_host_port_arg) |p| try allocator.dupe(u8, p) else null;

        return StealthBrowser{
            .allocator = allocator,
            .io = io,
            .child = std.mem.zeroes(process.Child),
            .profile_dir = "",
            .pid = null,
            .port = port,
            .proxy_host_port = proxy_owned,
        };
    }

    /// Clean up: kill VulpineOS process and free port
    pub fn deinit(self: *StealthBrowser) void {
        // Once PID ile öldür — varsa
        if (self.pid) |pid| {
            _ = std.c.kill(pid, std.posix.SIG.TERM);
            _ = std.os.linux.nanosleep(&std.os.linux.timespec{ .sec = 0, .nsec = 500 * std.time.ns_per_ms }, null);
            _ = std.c.kill(pid, std.posix.SIG.KILL);
            _ = std.os.linux.nanosleep(&std.os.linux.timespec{ .sec = 0, .nsec = 100 * std.time.ns_per_ms }, null);
            _ = std.c.waitpid(pid, null, std.os.linux.W.NOHANG);
        }
        // self.port'da dinleyen TÜM process'leri öldür
        // runuser + vulpineos.bin + camoufox zincirini temizler
        var fuser_buf: [64]u8 = undefined;
        const fuser_cmd = std.fmt.bufPrintZ(&fuser_buf, "fuser -k {d}/tcp 2>/dev/null", .{self.port}) catch return;
        _ = system(fuser_cmd.ptr);
        forceKillInstanceCamoufox(self.port);
    }

    /// Get the PID of the spawned process
    pub fn getPid(self: *const StealthBrowser) ?process.Child.Id {
        return self.pid;
    }

    /// Get the profile directory path
    pub fn getProfileDir(self: *const StealthBrowser) []const u8 {
        return self.profile_dir;
    }

    /// Get the CDP port
    pub fn getPort(self: *const StealthBrowser) u16 {
        return self.port;
    }
};

